    insert into public.tools (nombre, protocolo, descripcion) values ($q$IMAP/POP3$q$, $q$IMAP (143/993 tcp) POP3 (110/995 tcp)$q$, $q$Protocolos de lectura de correo. POP3 solo lista, descarga y borra mensajes; IMAP los mantiene sincronizados en el servidor y admite carpetas, acceso simultaneo de varios clientes y busqueda remota. Por defecto ambos van en claro (143 IMAP, 110 POP3) y transmiten usuario y contrasena en texto plano; los puertos 993 (IMAPS) y 995 (POP3S) usan TLS. En enumeracion buscamos el banner (Dovecot suele delatar version), las capacidades (AUTH=PLAIN, STARTTLS, STLS, SASL, LOGINDISABLED), el certificado (CN, organizacion) y probamos credenciales validas para listar carpetas o mensajes. Malas configuraciones tipicas: auth_debug, auth_debug_passwords, auth_verbose_passwords y auth_anonymous_username filtran datos sensibles. Herramientas clave: nmap, openssl s_client, ncat y curl.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -sC -p110,143,993,995 10.10.10.10$q$, $q$Escaneo de version y scripts por defecto sobre POP3, IMAP y sus variantes TLS. Suele revelar banner (Dovecot pop3d/imapd), capacidades y datos del certificado.$q$),
    (t_id, $q$nmap -p110,143 --script pop3-capabilities,imap-capabilities 10.10.10.10$q$, $q$Lista las capacidades soportadas por POP3 e IMAP (AUTH, SASL, STARTTLS/STLS, LOGINDISABLED, PIPELINING).$q$),
    (t_id, $q$nmap -p143 --script imap-ntlm-info 10.10.10.10$q$, $q$Si IMAP acepta NTLM, extrae informacion del dominio y del host a traves del challenge.$q$),
    (t_id, $q$openssl s_client -connect 10.10.10.10:993 -crlf -quiet$q$, $q$Sesion IMAPS interactiva sobre TLS para hablar el protocolo a mano (LOGIN, LIST, SELECT, FETCH).$q$),
    (t_id, $q$openssl s_client -connect 10.10.10.10:995 -crlf -quiet$q$, $q$Sesion POP3S interactiva sobre TLS para hablar POP3 a mano (USER, PASS, LIST, RETR).$q$),
    (t_id, $q$openssl s_client -connect 10.10.10.10:imaps$q$, $q$Igual que arriba pero usando el alias imaps del puerto. Muestra el certificado (CN, O, ST) y el banner del IMAP.$q$),
    (t_id, $q$openssl s_client -connect 10.10.10.10:pop3s$q$, $q$Conexion a POP3S por alias del puerto. Muestra el certificado y el banner (+OK ... POP3 Server).$q$),
    (t_id, $q$ncat --ssl 10.10.10.10 993$q$, $q$Alternativa a openssl para abrir una sesion IMAPS cruda con ncat sobre TLS.$q$),
    (t_id, $q$curl -k 'imaps://10.10.10.10' --user robin:robin$q$, $q$Se autentica contra IMAPS con curl aceptando el certificado autofirmado y lista las carpetas del buzon.$q$),
    (t_id, $q$curl -k 'imaps://10.10.10.10' --user robin:robin -v$q$, $q$Igual que la anterior pero en modo verbose: muestra el handshake TLS, el certificado y los comandos IMAP intercambiados.$q$),
    (t_id, $q$curl -k 'pop3s://10.10.10.10' --user robin:robin$q$, $q$Se autentica contra POP3S con curl y lista los mensajes disponibles del buzon.$q$),
    (t_id, $q$1 LOGIN robin robin$q$, $q$Dentro de una sesion IMAP, autentica al usuario robin con contrasena robin. El '1' es el tag del comando.$q$),
    (t_id, $q$1 LIST "" *$q$, $q$Dentro de una sesion IMAP autenticada, lista todos los buzones/carpetas del usuario.$q$),
    (t_id, $q$1 SELECT INBOX$q$, $q$Selecciona el buzon INBOX para poder leer sus mensajes con FETCH.$q$),
    (t_id, $q$1 FETCH 1 all$q$, $q$Recupera todos los datos asociados al mensaje con ID 1 del buzon seleccionado.$q$),
    (t_id, $q$1 LOGOUT$q$, $q$Cierra la sesion IMAP con el servidor.$q$),
    (t_id, $q$USER robin$q$, $q$Dentro de una sesion POP3, identifica al usuario robin.$q$),
    (t_id, $q$PASS robin$q$, $q$Dentro de una sesion POP3, envia la contrasena del usuario ya identificado con USER.$q$),
    (t_id, $q$LIST$q$, $q$Dentro de una sesion POP3, pide al servidor el numero y tamano de todos los mensajes.$q$),
    (t_id, $q$RETR 1$q$, $q$Dentro de una sesion POP3, descarga el mensaje con ID 1.$q$),
    (t_id, $q$QUIT$q$, $q$Cierra la sesion con el servidor POP3.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres hacer un escaneo de version y scripts por defecto sobre los cuatro puertos de POP3 e IMAP (110, 143, 993, 995) en 10.10.10.10. Escribe el comando.$q$, array[$q$nmap -sV -sC -p110,143,993,995 10.10.10.10$q$, $q$nmap -sC -sV -p110,143,993,995 10.10.10.10$q$]::text[], $q$Combina -sV y -sC con la lista de los cuatro puertos separados por coma.$q$, $q$nmap -sV -sC -p110,143,993,995 10.10.10.10 cubre POP3 (110), IMAP (143) y sus variantes TLS (995 y 993). Trae banner (suele decir Dovecot pop3d/imapd), capacidades y datos del certificado (CN, O, ST). Es el arranque obligatorio antes de autenticarte o probar credenciales.$q$),
    (t_id, $q$Quieres listar las capacidades soportadas por los servicios POP3 e IMAP de 10.10.10.10 en un solo comando con nmap. Escribe el comando.$q$, array[$q$nmap -p110,143 --script pop3-capabilities,imap-capabilities 10.10.10.10$q$, $q$nmap --script pop3-capabilities,imap-capabilities -p110,143 10.10.10.10$q$]::text[], $q$Junta los scripts pop3-capabilities e imap-capabilities separados por coma en --script.$q$, $q$nmap -p110,143 --script pop3-capabilities,imap-capabilities 10.10.10.10 dice que mecanismos de autenticacion (LOGIN, PLAIN, NTLM, CRAM-MD5) y extensiones acepta el servidor (STARTTLS, STLS, SASL, PIPELINING, LOGINDISABLED). Ver AUTH=PLAIN sin TLS o NTLM disponible te orienta el ataque.$q$),
    (t_id, $q$Quieres abrir una sesion cifrada con IMAPS (puerto 993) en 10.10.10.10 usando openssl s_client, en modo silencioso y con salto de linea CRLF. Escribe el comando.$q$, array[$q$openssl s_client -connect 10.10.10.10:993 -crlf -quiet$q$, $q$openssl s_client -connect 10.10.10.10:993 -quiet -crlf$q$]::text[], $q$Es openssl s_client, con -connect IP:993 y los flags -crlf y -quiet.$q$, $q$openssl s_client -connect 10.10.10.10:993 -crlf -quiet te da el equivalente de telnet pero sobre TLS. -crlf manda saltos de linea correctos y -quiet oculta el ruido del handshake para hablar IMAP directo (1 LOGIN usuario pass, 1 LIST "" *, 1 SELECT INBOX, etc.).$q$),
    (t_id, $q$Quieres abrir una sesion POP3S contra 10.10.10.10 usando openssl s_client con el alias del puerto (pop3s) para ver el certificado y el banner. Escribe el comando.$q$, array[$q$openssl s_client -connect 10.10.10.10:pop3s$q$]::text[], $q$openssl s_client -connect IP:<alias>, donde el alias es el nombre del servicio POP3 sobre TLS.$q$, $q$openssl s_client -connect 10.10.10.10:pop3s abre TLS al 995 y muestra el certificado (CN, O, ST) y el banner +OK ... POP3 Server. Sirve para enumerar version del servidor y datos de la organizacion antes de probar credenciales.$q$),
    (t_id, $q$Quieres autenticarte contra IMAPS en 10.10.10.10 con el usuario robin y la contrasena robin usando curl, aceptando el certificado autofirmado. Escribe el comando.$q$, array[$q$curl -k 'imaps://10.10.10.10' --user robin:robin$q$, $q$curl -k imaps://10.10.10.10 --user robin:robin$q$, $q$curl -k 'imaps://10.10.10.10' -u robin:robin$q$, $q$curl -k imaps://10.10.10.10 -u robin:robin$q$]::text[], $q$curl con -k para ignorar el certificado, la URL imaps:// y --user usuario:contrasena.$q$, $q$curl -k 'imaps://10.10.10.10' --user robin:robin prueba credenciales contra IMAPS de forma rapida. -k acepta certificados autofirmados. Si las credenciales son buenas, curl te devuelve la lista de carpetas del buzon (INBOX, Important, etc.).$q$),
    (t_id, $q$Quieres hacer lo mismo que antes pero en modo verbose para ver el handshake TLS, el certificado y los comandos IMAP intercambiados. Escribe el comando.$q$, array[$q$curl -k 'imaps://10.10.10.10' --user robin:robin -v$q$, $q$curl -k -v 'imaps://10.10.10.10' --user robin:robin$q$, $q$curl -v -k 'imaps://10.10.10.10' --user robin:robin$q$, $q$curl -k imaps://10.10.10.10 --user robin:robin -v$q$, $q$curl -kv 'imaps://10.10.10.10' --user robin:robin$q$]::text[], $q$Anade -v al comando de curl con IMAPS.$q$, $q$curl -k 'imaps://10.10.10.10' --user robin:robin -v ademas de listar las carpetas te muestra el handshake TLS, la version usada, el certificado del servidor (CN, emisor, fechas) y los comandos IMAP (A001 CAPABILITY, A002 AUTHENTICATE PLAIN, A003 LIST). Es lo que usas para enumerar version del servidor y detalles de la organizacion.$q$),
    (t_id, $q$Estas dentro de una sesion IMAP interactiva y quieres autenticarte como el usuario robin con la contrasena robin. Escribe el comando IMAP (usa el tag 1).$q$, array[$q$1 LOGIN robin robin$q$, $q$1 login robin robin$q$]::text[], $q$El verbo IMAP para autenticar es LOGIN y va precedido de un tag (por ejemplo 1).$q$, $q$1 LOGIN robin robin autentica al usuario robin con la contrasena robin. En IMAP cada comando lleva un tag (1, A001, a1...) para que el servidor pueda correlacionar la respuesta. Si el login es correcto, el servidor responde '1 OK Logged in' y ya puedes ejecutar LIST o SELECT.$q$),
    (t_id, $q$Ya autenticado en la sesion IMAP, quieres listar todas las carpetas del buzon del usuario. Escribe el comando IMAP (usa el tag 1).$q$, array[$q$1 LIST "" *$q$, $q$1 list "" *$q$]::text[], $q$El verbo es LIST, con referencia vacia ("") y patron * para pedir todas.$q$, $q$1 LIST "" * lista todos los buzones o carpetas visibles para el usuario (INBOX, Important, Sent, etc.). El primer argumento es la referencia (vacia = raiz) y el segundo el patron (* = todo). Es el paso siguiente al LOGIN para saber que carpetas puedes explorar con SELECT y FETCH.$q$),
    (t_id, $q$Estas dentro de una sesion POP3 interactiva y quieres identificarte como el usuario robin. Escribe el comando POP3.$q$, array[$q$USER robin$q$, $q$user robin$q$]::text[], $q$El primer verbo POP3 para dar el nombre de usuario son cuatro letras.$q$, $q$USER robin le dice al servidor POP3 el nombre del usuario. Es el primer paso de la autenticacion en POP3 clasico: primero USER, luego PASS <contrasena>. Si el usuario existe, el servidor responde +OK y espera la contrasena.$q$),
    (t_id, $q$Ya identificado con USER, quieres enviar la contrasena robin para autenticarte. Escribe el comando POP3.$q$, array[$q$PASS robin$q$, $q$pass robin$q$]::text[], $q$El verbo POP3 para la contrasena son cuatro letras y empieza por P.$q$, $q$PASS robin envia la contrasena en texto plano al servidor POP3 (por eso conviene POP3S en 995). Si la autenticacion es correcta, el servidor responde +OK y ya puedes usar LIST y RETR para ver y descargar los mensajes.$q$);
