do $seed$
declare t_id uuid;
begin
  select id into t_id from public.tools where nombre = $q$IMAP/POP3$q$ order by created_at limit 1;
  if t_id is null then
  else
    update public.tools set protocolo = $q$IMAP (143/993 tcp) POP3 (110/995 tcp)$q$, descripcion = $q$Protocolos de lectura de correo. POP3 solo lista, descarga y borra mensajes; IMAP los mantiene sincronizados en el servidor y admite carpetas, acceso simultaneo de varios clientes y busqueda remota. Por defecto ambos van en claro (143 IMAP, 110 POP3) y transmiten usuario y contrasena en texto plano; los puertos 993 (IMAPS) y 995 (POP3S) usan TLS. En enumeracion buscamos el banner (Dovecot suele delatar version), las capacidades (AUTH=PLAIN, STARTTLS, STLS, SASL, LOGINDISABLED), el certificado (CN, organizacion) y probamos credenciales validas para listar carpetas o mensajes. Malas configuraciones tipicas: auth_debug, auth_debug_passwords, auth_verbose_passwords y auth_anonymous_username filtran datos sensibles. Herramientas clave: nmap, openssl s_client, ncat y curl.$q$ where id = t_id;
    delete from public.commands where tool_id = t_id;
    delete from public.exercises where tool_id = t_id;
  end if;
end
$seed$;